import manifest from "./static-manifest.json";

// Card images for cards defined in code rather than Sanity (the AI Lab
// section cards; workshops are Sanity documents with their own cardImage). Generated by
// `npx tsx scripts/generate-card-images.ts --static --confirm` into
// public/images/cards/, and recorded in static-manifest.json. An entry
// marked "manual": true is a hand-made image the script never replaces.
// Safe to import from client components: it's only the JSON.

export type StaticCardEntry = { src: string; hash?: string; manual?: boolean };

const entries = manifest as Record<string, StaticCardEntry>;

export const staticCardKey = {
  section: (href: string) => `section${href.replace(/\//g, "-")}`,
};

export function staticCardImage(key: string): string | undefined {
  return entries[key]?.src;
}
